// -----------------------------------------------------------------------------
// Globals.cs
// -----------------------------------------------------------------------------
// Provides application-wide global settings and utilities, such as start time,
// markdown processing pipeline, authentication cookie placeholder, public base URL,
// and assembly version information.
// -----------------------------------------------------------------------------
using Bovis.Interfaces.Configuration;
using Bovis.Storage;
using Markdig;
using Markdig.Extensions.AutoLinks;
using System.Reflection;
using System.Runtime.CompilerServices;
[assembly: InternalsVisibleTo("Bovis.Web.Test")]
[assembly:Configurable]

namespace Bovis.Web
{
    /// <summary>
    /// Holds static global values used throughout the Bovis.Web application.
    /// </summary>
    [Configurable("Bovis.Web")]
    internal static class Globals
    {
        /// <summary>
        /// The timestamp when the application started.
        /// </summary>
        public static DateTime StartTime { get; set; }

        /// <summary>
        /// Authentication cookie value. Initiailized to a random string to avoid accidental matches. Can be overridden with a fixed value in configuration.
        /// </summary>
        [Configurable]
        public static string AuthCookie = RandomString(20); 
        static string RandomString(int length)
        {
            const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
            var random = new Random();
            return new string(Enumerable.Repeat(chars, length)
              .Select(s => s[random.Next(s.Length)]).ToArray());
        }
        /// <summary>
        /// Base URL for the public-facing part of the application (non-authenticated resources).
        /// </summary>
        [Configurable]
        public static string PublicBaseUrl { get; set; }  = "/";

        /// <summary>
        /// Enable swagger documentation for the API. (Default: false)
        /// </summary>
        [Configurable]
        public static bool EnableSwagger { get; set; } = false;
        /// <summary>
        /// Enable authentication negotiation. (Default: false)
        /// </summary>
        [Configurable]
        public static bool EnableAuthNegotiation { get; set; } = false;

        /// <summary>
        /// Retrieves the version string of the currently executing assembly, or "unknown" if unavailable.
        /// </summary>
        public static string Version => Assembly.GetExecutingAssembly().GetName().Version?.ToString() ?? "unknown";

        /// <summary>
        /// Indicates whether internal authentication should be used. (Default: true)
        /// </summary>
        [Configurable]
        public static bool UseInternalAuth { get; set; } = true; 
    }
