// -----------------------------------------------------------------------------
// UserContext.cs
// -----------------------------------------------------------------------------
// Provides a UserContext class that encapsulates HTTP context information,
// determines the current user's group based on an authentication cookie, and
// exposes the current user name and group.
// -----------------------------------------------------------------------------
namespace Bovis.Web
{

    /// <summary>
    /// Represents the context of the currently logged‑in user.
    /// </summary>
    /// <param name="ctx">The <see cref="HttpContext"/> associated with the request; may be null.</param>
    public class UserContext(HttpContext? ctx)
    {
        /// <summary>
        /// Gets the underlying <see cref="HttpContext"/> instance.
        /// </summary>
        public HttpContext? HttpContext => ctx;

        /// <summary>
        /// Name of the administrator group.
        /// </summary>
        public static readonly string AdminGroup = "Admin";

        /// <summary>
        /// Name of the regular user group.
        /// </summary>
        public static readonly string UserGroup = "User";

        /// <summary>
        /// Gets the name of the current user.
        /// </summary>
        public string CurrentUser { get; private set; } = "CurrentUser";

        /// <summary>
        /// Determines the group of the current user based on the presence and value of an authentication cookie.
        /// </summary>
        public string CurrentGroup
        {
            get
            {
                // If the authentication cookie matches the expected value, treat the user as an admin.
                if (CheckCookie("bovis_auth_cookie", Bovis.Web.Globals.AuthCookie))
                {
                    return AdminGroup;
                }

                // Otherwise, the user belongs to the regular user group.
                return UserGroup;
            }
        }

        /// <summary>
        /// Checks whether a specific cookie exists and matches a given value.
        /// </summary>
        /// <param name="cookieName">The name of the cookie to look for.</param>
        /// <param name="value">The expected value of the cookie.</param>
        /// <returns>
        /// <c>true</c> if the cookie is present and its value equals <paramref name="value"/>; otherwise, <c>false</c>.
        /// </returns>
        private bool CheckCookie(string cookieName, string value)
        {
            try
            {
                // If there is no HttpContext, we cannot access cookies.
                if (ctx == null) return false;

                // Verify the cookie collection contains the target cookie.
                if (ctx.Request.Cookies.ContainsKey(cookieName))
                {
                    // Return true only if the cookie's value matches the expected value.
                    return ctx.Request.Cookies[cookieName] == value;
                }

                // Cookie not found.
                return false;
            }
            catch (Exception)
            {
                // If we cannot access the cookies (e.g., due to an unexpected error),
                // assume the user is not authenticated.
                return false;
            }
        }
    }
